#include <cstdint>

// Specialized contract:
// x: [128,4096,4095] float32 contiguous, reduce dim=1 => y: [128,4095] int64 indices
//
// ARA With-Index implementation: one task per batch, seven reduction rows per
// padded GM->UB transfer, and vector Compare/Select state updates over A0.

class KernelArgmaxOverADimensionCustom {
public:
    __aicore__ inline KernelArgmaxOverADimensionCustom() {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y,
                               uint32_t batch, uint32_t reduceDim, uint32_t innerDim,
                               uint32_t tileInner, uint32_t alignedInner,
                               uint32_t reductionChunk, uint32_t tilesPerBatch)
    {
        batch_ = batch;
        reduceDim_ = reduceDim;
        innerDim_ = innerDim;
        tileInner_ = tileInner;
        alignedInner_ = alignedInner;
        reductionChunk_ = reductionChunk;
        tilesPerBatch_ = tilesPerBatch;

        xGm_.SetGlobalBuffer((__gm__ float*)x);
        yGm_.SetGlobalBuffer((__gm__ int64_t*)y);

        pipe_.InitBuffer(inputQueue_, 1, REDUCTION_CHUNK * ALIGNED_INNER * sizeof(float));
        pipe_.InitBuffer(maxBuf_, ALIGNED_INNER * sizeof(float));
        pipe_.InitBuffer(indexBuf_, ALIGNED_INNER * sizeof(float));
        pipe_.InitBuffer(maskBuf_, ALIGNED_INNER * sizeof(uint8_t));
        pipe_.InitBuffer(outputQueue_, 1, ALIGNED_INNER * sizeof(int64_t));
    }

    __aicore__ inline void Process()
    {
        if (batch_ == 0 || reduceDim_ == 0 || innerDim_ == 0 || tileInner_ == 0 ||
            alignedInner_ == 0 || reductionChunk_ == 0 || tilesPerBatch_ == 0) {
            return;
        }

        const uint32_t blockIdx = (uint32_t)AscendC::GetBlockIdx();
        const uint32_t b = blockIdx / tilesPerBatch_;
        const uint32_t tileId = blockIdx - b * tilesPerBatch_;
        if (b >= batch_) {
            return;
        }

        if (tileId != 0 || tileInner_ != innerDim_ || alignedInner_ != ALIGNED_INNER ||
            reductionChunk_ != REDUCTION_CHUNK) {
            return;
        }

        const uint64_t batchBase = (uint64_t)b * (uint64_t)reduceDim_ * (uint64_t)innerDim_;
        AscendC::LocalTensor<float> maxLocal = maxBuf_.Get<float>();
        AscendC::LocalTensor<float> indexLocal = indexBuf_.Get<float>();
        AscendC::LocalTensor<uint8_t> maskLocal = maskBuf_.Get<uint8_t>();
        AscendC::Duplicate(maxLocal, -3.402823466e+38f, (int32_t)alignedInner_);
        AscendC::Duplicate(indexLocal, 0.0f, (int32_t)alignedInner_);
        float rowIndex = 0.0f;

        for (uint32_t r0 = 0; r0 < reduceDim_; r0 += reductionChunk_) {
            const uint32_t validRows = (r0 + reductionChunk_ <= reduceDim_) ?
                reductionChunk_ : (reduceDim_ - r0);
            AscendC::LocalTensor<float> inputLocal = inputQueue_.AllocTensor<float>();
            AscendC::DataCopyExtParams copyParams{
                (uint16_t)validRows, innerDim_ * (uint32_t)sizeof(float), 0, 0, 0};
            AscendC::DataCopyPadExtParams<float> padParams{true, 0, 1, -3.402823466e+38f};
            AscendC::DataCopyPad(inputLocal, xGm_[batchBase + (uint64_t)r0 * innerDim_],
                                 copyParams, padParams);
            inputQueue_.EnQue(inputLocal);
            inputLocal = inputQueue_.DeQue<float>();

            for (uint32_t rr = 0; rr < validRows; ++rr) {
                AscendC::LocalTensor<float> rowLocal = inputLocal[rr * alignedInner_];
                AscendC::Compare(maskLocal, rowLocal, maxLocal, AscendC::CMPMODE::GT, alignedInner_);
                AscendC::PipeBarrier<PIPE_V>();
                AscendC::Select(maxLocal, maskLocal, rowLocal, maxLocal,
                                AscendC::SELMODE::VSEL_TENSOR_TENSOR_MODE, alignedInner_);
                AscendC::Duplicate(rowLocal, rowIndex, (int32_t)alignedInner_);
                AscendC::PipeBarrier<PIPE_V>();
                AscendC::Select(indexLocal, maskLocal, rowLocal, indexLocal,
                                AscendC::SELMODE::VSEL_TENSOR_TENSOR_MODE, alignedInner_);
                AscendC::PipeBarrier<PIPE_V>();
                rowIndex += 1.0f;
            }
            inputQueue_.FreeTensor(inputLocal);
        }

        AscendC::LocalTensor<int64_t> outputLocal = outputQueue_.AllocTensor<int64_t>();
        for (uint32_t i = 0; i < innerDim_; ++i) {
            outputLocal.SetValue(i, (int64_t)indexLocal.GetValue(i));
        }
        outputQueue_.EnQue(outputLocal);
        outputLocal = outputQueue_.DeQue<int64_t>();
        AscendC::TEventID sToMte3 = pipe_.FetchEventID<AscendC::HardEvent::S_MTE3>();
        AscendC::SetFlag<AscendC::HardEvent::S_MTE3>(sToMte3);
        AscendC::WaitFlag<AscendC::HardEvent::S_MTE3>(sToMte3);
        AscendC::DataCopyExtParams outParams{1, innerDim_ * (uint32_t)sizeof(int64_t), 0, 0, 0};
        AscendC::DataCopyPad(yGm_[(uint64_t)b * innerDim_], outputLocal, outParams);
        outputQueue_.FreeTensor(outputLocal);
    }

private:
    static constexpr uint32_t ALIGNED_INNER = 4096;
    static constexpr uint32_t REDUCTION_CHUNK = 7;
    AscendC::TPipe pipe_;
    AscendC::TQue<AscendC::TPosition::VECIN, 1> inputQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, 1> outputQueue_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> maxBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> indexBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> maskBuf_;
    AscendC::GlobalTensor<float> xGm_;
    AscendC::GlobalTensor<int64_t> yGm_;
    uint32_t batch_{0};
    uint32_t reduceDim_{0};
    uint32_t innerDim_{0};
    uint32_t tileInner_{0};
    uint32_t alignedInner_{0};
    uint32_t reductionChunk_{0};
    uint32_t tilesPerBatch_{0};
};

extern "C" __global__ __aicore__ void argmax_over_a_dimension_custom(
    GM_ADDR x, GM_ADDR y, GM_ADDR workspace, GM_ADDR tiling)
{
    (void)workspace;
    GET_TILING_DATA(tiling_data, tiling);
    KernelArgmaxOverADimensionCustom op;
    op.Init(x, y,
            tiling_data.batch, tiling_data.reduceDim, tiling_data.innerDim,
            tiling_data.tileInner, tiling_data.alignedInner,
            tiling_data.reductionChunk, tiling_data.tilesPerBatch);
    op.Process();
}

