#include "kernel_operator.h"
#include <cstdint>

// Specialized contract:
// x: [128,4096,4095] float32 contiguous, reduce dim=1 => y: [128,4095] int64 indices
//
// Mapping: each AIV core processes whole batches with b=blockIdx+k*blockNum.
//
// Tie-breaking:
// strict less-than => first occurrence wins (matches PyTorch default behavior).

class KernelArgminOverADimensionCustom {
public:
    static constexpr uint32_t INNER = 4095;
    static constexpr uint32_t ALIGNED_INNER = 4096;
    static constexpr uint32_t R_CHUNK = 8;
    static constexpr uint32_t INPUT_ELEMS = R_CHUNK * ALIGNED_INNER;
    static constexpr uint32_t INPUT_BYTES = INPUT_ELEMS * sizeof(float);
    static constexpr uint32_t OUTPUT_BYTES = ALIGNED_INNER * sizeof(int64_t);
    static constexpr uint32_t MASK_BYTES = ALIGNED_INNER / 8;

    __aicore__ inline KernelArgminOverADimensionCustom() {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y,
                               uint32_t /*totalX*/, uint32_t /*totalY*/,
                               uint32_t batch, uint32_t reduceDim, uint32_t innerDim,
                               uint32_t unrollR)
    {
        batch_ = batch;
        reduceDim_ = reduceDim;
        innerDim_ = innerDim;
        unrollR_ = (unrollR == 0 ? 1u : unrollR);

        xGm_.SetGlobalBuffer((__gm__ float*)x);
        yGm_.SetGlobalBuffer((__gm__ int64_t*)y);

        pipe_.InitBuffer(inputQueue_, 1, INPUT_BYTES);
        pipe_.InitBuffer(outputQueue_, 1, OUTPUT_BYTES);
        pipe_.InitBuffer(maskBuf_, MASK_BYTES);
    }

    __aicore__ inline void Process()
    {
        if (batch_ == 0 || reduceDim_ == 0 || innerDim_ == 0) return;

        const uint32_t blockNum = (uint32_t)AscendC::GetBlockNum();
        const uint32_t blockIdx = (uint32_t)AscendC::GetBlockIdx();
        if (blockNum == 0) return;

        if (innerDim_ != INNER || reduceDim_ != 4096 || unrollR_ != R_CHUNK) return;

        for (uint32_t b = blockIdx; b < batch_; b += blockNum) {
            ProcessBatch(b);
        }
    }

private:
    __aicore__ inline void CopyIn(uint64_t gmOffset)
    {
        AscendC::LocalTensor<float> input = inputQueue_.AllocTensor<float>();
        AscendC::DataCopyExtParams copyInParams{
            R_CHUNK, INNER * sizeof(float), 0, 0, 0};
        AscendC::DataCopyPadExtParams<float> padParams{true, 0, 1, 0.0f};
        AscendC::DataCopyPad(input, xGm_[gmOffset], copyInParams, padParams);
        inputQueue_.EnQue(input);
    }

    __aicore__ inline void UpdateState(const AscendC::LocalTensor<float>& best,
                                       const AscendC::LocalTensor<float>& indices,
                                       const AscendC::LocalTensor<uint8_t>& mask,
                                       const AscendC::LocalTensor<float>& row,
                                       float rowIndex)
    {
        // Keep the old value/index when old <= new, including equality.
        AscendC::Compare(mask, best, row, AscendC::CMPMODE::LE, ALIGNED_INNER);
        AscendC::Select(best, mask, best, row,
                        AscendC::SELMODE::VSEL_TENSOR_TENSOR_MODE, ALIGNED_INNER);
        AscendC::Select(indices, mask, indices, rowIndex,
                        AscendC::SELMODE::VSEL_TENSOR_SCALAR_MODE, ALIGNED_INNER);
    }

    __aicore__ inline void ProcessBatch(uint32_t b)
    {
        AscendC::LocalTensor<int64_t> output = outputQueue_.AllocTensor<int64_t>();
        AscendC::LocalTensor<float> state = output.template ReinterpretCast<float>();
        AscendC::LocalTensor<float> best = state;
        AscendC::LocalTensor<float> indices = state[ALIGNED_INNER];
        AscendC::LocalTensor<uint8_t> mask = maskBuf_.Get<uint8_t>();

        const uint64_t batchBase = static_cast<uint64_t>(b) * reduceDim_ * INNER;
        float rowIndex = 0.0f;
        for (uint32_t r0 = 0; r0 < reduceDim_; r0 += R_CHUNK) {
            CopyIn(batchBase + static_cast<uint64_t>(r0) * INNER);
            AscendC::LocalTensor<float> input = inputQueue_.DeQue<float>();

            uint32_t row = 0;
            if (r0 == 0) {
                AscendC::DataCopy(best, input, ALIGNED_INNER);
                AscendC::Duplicate(indices, 0.0f, ALIGNED_INNER);
                row = 1;
                rowIndex = 1.0f;
            }
            for (; row < R_CHUNK; ++row) {
                UpdateState(best, indices, mask, input[row * ALIGNED_INNER], rowIndex);
                rowIndex += 1.0f;
            }
            inputQueue_.FreeTensor(input);
        }

        // DAV_2201 has no direct FP32->INT64 Vector cast. Pack indices first,
        // then convert backwards with Scalar so the aliased source stays intact.
        AscendC::DataCopy(state, indices, ALIGNED_INNER);
        AscendC::PipeBarrier<PIPE_V>();
        event_t eventVToS = static_cast<event_t>(GetTPipePtr()->FetchEventID(
            AscendC::HardEvent::V_S));
        AscendC::SetFlag<AscendC::HardEvent::V_S>(eventVToS);
        AscendC::WaitFlag<AscendC::HardEvent::V_S>(eventVToS);
        for (int32_t i = static_cast<int32_t>(INNER) - 1; i >= 0; --i) {
            output.SetValue(static_cast<uint32_t>(i),
                            static_cast<int64_t>(state.GetValue(static_cast<uint32_t>(i))));
        }

        outputQueue_.EnQue(output);
        AscendC::LocalTensor<int64_t> ready = outputQueue_.DeQue<int64_t>();
        event_t eventSToMte3 = static_cast<event_t>(GetTPipePtr()->FetchEventID(
            AscendC::HardEvent::S_MTE3));
        AscendC::SetFlag<AscendC::HardEvent::S_MTE3>(eventSToMte3);
        AscendC::WaitFlag<AscendC::HardEvent::S_MTE3>(eventSToMte3);
        AscendC::DataCopyExtParams copyOutParams{1, INNER * sizeof(int64_t), 0, 0, 0};
        AscendC::DataCopyPad(yGm_[static_cast<uint64_t>(b) * INNER], ready, copyOutParams);
        outputQueue_.FreeTensor(ready);
    }

    AscendC::TPipe pipe_;
    AscendC::TQue<AscendC::QuePosition::VECIN, 1> inputQueue_;
    AscendC::TQue<AscendC::QuePosition::VECOUT, 1> outputQueue_;
    AscendC::TBuf<AscendC::QuePosition::VECCALC> maskBuf_;
    AscendC::GlobalTensor<float> xGm_;
    AscendC::GlobalTensor<int64_t> yGm_;
    uint32_t batch_{0};
    uint32_t reduceDim_{0};
    uint32_t innerDim_{0};
    uint32_t unrollR_{1};
};

extern "C" __global__ __aicore__ void argmin_over_a_dimension_custom(
    GM_ADDR x, GM_ADDR y, GM_ADDR workspace, GM_ADDR tiling)
{
    (void)workspace;
    GET_TILING_DATA(tiling_data, tiling);
    KernelArgminOverADimensionCustom op;
    op.Init(x, y,
            tiling_data.totalX, tiling_data.totalY,
            tiling_data.batch, tiling_data.reduceDim, tiling_data.innerDim,
            tiling_data.unrollR);
    op.Process();
}

