#include "kernel_operator.h"

// Specialized AvgPool1d for this benchmark/model instance:
// kernel_size=8, stride=1, padding=4
// count_include_pad=True: always divide by 8, padded positions contribute 0.
//
// Optimization:
// 1) Multi-block: each block processes a contiguous range of flattened output indices.
// 2) Sliding window running-sum within each (n,c) row segment to reduce loads to ~2/output.

class KernelAveragePooling1dCustom {
public:
    __aicore__ inline KernelAveragePooling1dCustom() {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y,
                               uint32_t totalX, uint32_t totalY,
                               uint32_t n, uint32_t c,
                               uint32_t l_in, uint32_t l_out,
                               uint32_t nc, uint32_t tileLen)
    {
        (void)totalX;
        this->totalY = totalY;
        this->n = n;
        this->c = c;
        this->l_in = l_in;
        this->l_out = l_out;
        this->nc = nc;
        this->tileLen = tileLen;

        xGm.SetGlobalBuffer((__gm__ float*)x);
        yGm.SetGlobalBuffer((__gm__ float*)y);
        pipe.InitBuffer(inputQueue, 1, 24544 * sizeof(float));
        pipe.InitBuffer(outputQueue, 1, 24536 * sizeof(float));
    }

    __aicore__ inline float LoadPadZero(const AscendC::LocalTensor<float>& xLocal,
                                       uint32_t localPos) const
    {
        return xLocal.GetValue(localPos);
    }

    __aicore__ inline float InitWindowSum(const AscendC::LocalTensor<float>& xLocal) const
    {
        float sum = 0.0f;
        sum += LoadPadZero(xLocal, 0);
        sum += LoadPadZero(xLocal, 1);
        sum += LoadPadZero(xLocal, 2);
        sum += LoadPadZero(xLocal, 3);
        sum += LoadPadZero(xLocal, 4);
        sum += LoadPadZero(xLocal, 5);
        sum += LoadPadZero(xLocal, 6);
        sum += LoadPadZero(xLocal, 7);
        return sum;
    }

    __aicore__ inline void ProcessRowSegment(uint32_t nc_idx, uint32_t out_begin, uint32_t out_end)
    {
        constexpr int32_t P = 4;
        const float invK = 1.0f / 8.0f;

        const uint64_t xBase = static_cast<uint64_t>(nc_idx) * l_in;
        const uint64_t yBase = static_cast<uint64_t>(nc_idx) * l_out;
        const uint32_t validOut = out_end - out_begin;

        const int32_t requestedBegin = static_cast<int32_t>(out_begin) - P;
        const int32_t requestedEnd = static_cast<int32_t>(out_end) + 3;
        const uint32_t validBegin = requestedBegin < 0 ? 0 : static_cast<uint32_t>(requestedBegin);
        const uint32_t validEnd = requestedEnd > static_cast<int32_t>(l_in)
                                      ? l_in
                                      : static_cast<uint32_t>(requestedEnd);
        const uint32_t validInput = validEnd - validBegin;
        const uint8_t leftPad = requestedBegin < 0 ? static_cast<uint8_t>(-requestedBegin) : 0;
        const uint8_t rightPad = requestedEnd > static_cast<int32_t>(l_in)
                                     ? static_cast<uint8_t>(requestedEnd - static_cast<int32_t>(l_in))
                                     : 0;

        AscendC::LocalTensor<float> xLocal = inputQueue.AllocTensor<float>();
        AscendC::DataCopyExtParams inputCopy{
            1, static_cast<uint32_t>(validInput * sizeof(float)), 0, 0, 0};
        AscendC::DataCopyPadExtParams<float> inputPad{true, leftPad, rightPad, 0.0f};
        AscendC::DataCopyPad(xLocal, xGm[xBase + validBegin], inputCopy, inputPad);
        inputQueue.EnQue(xLocal);
        xLocal = inputQueue.DeQue<float>();

        AscendC::LocalTensor<float> yLocal = outputQueue.AllocTensor<float>();

        // Initialize sum for the first output of this segment.
        float sum = InitWindowSum(xLocal);

        // Write first output.
        yLocal.SetValue(0, sum * invK);

        // Slide within [out_begin+1, out_end)
        for (uint32_t localOut = 1; localOut < validOut; ++localOut) {
            sum -= LoadPadZero(xLocal, localOut - 1);
            sum += LoadPadZero(xLocal, localOut + 7);
            yLocal.SetValue(localOut, sum * invK);
        }

        inputQueue.FreeTensor(xLocal);
        outputQueue.EnQue(yLocal);
        yLocal = outputQueue.DeQue<float>();
        AscendC::DataCopyExtParams outputCopy{
            1, static_cast<uint32_t>(validOut * sizeof(float)), 0, 0, 0};
        AscendC::DataCopyPad(yGm[yBase + out_begin], yLocal, outputCopy);
        outputQueue.FreeTensor(yLocal);
    }

    __aicore__ inline void Process()
    {
        const uint32_t blockIdx = AscendC::GetBlockIdx();
        const uint32_t blockDim = AscendC::GetBlockNum();

        if (blockIdx >= nc) return;

        for (uint32_t nc_idx = blockIdx; nc_idx < nc; nc_idx += blockDim) {
            for (uint32_t outBegin = 0; outBegin < l_out; outBegin += tileLen) {
                const uint32_t remaining = l_out - outBegin;
                const uint32_t validOut = remaining < tileLen ? remaining : tileLen;
                ProcessRowSegment(nc_idx, outBegin, outBegin + validOut);
            }
        }
    }

private:
    AscendC::GlobalTensor<float> xGm;
    AscendC::GlobalTensor<float> yGm;
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::QuePosition::VECIN, 1> inputQueue;
    AscendC::TQue<AscendC::QuePosition::VECOUT, 1> outputQueue;
    uint32_t totalY;
    uint32_t n, c, l_in, l_out, nc, tileLen;
};

