#include "kernel_operator.h"

class KernelAveragePooling3dCustom {
public:
    __aicore__ inline KernelAveragePooling3dCustom() {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y,
                               uint32_t n, uint32_t c,
                               uint32_t d_in, uint32_t h_in, uint32_t w_in,
                               uint32_t d_out, uint32_t h_out, uint32_t w_out,
                               uint32_t rows, uint32_t rowsPerBlock)
    {
        this->n = n;
        this->c = c;
        this->d_in = d_in;
        this->h_in = h_in;
        this->w_in = w_in;
        this->d_out = d_out;
        this->h_out = h_out;
        this->w_out = w_out;
        this->rows = rows;
        this->rowsPerBlock = rowsPerBlock;

        xGm.SetGlobalBuffer((__gm__ float*)x);
        yGm.SetGlobalBuffer((__gm__ float*)y);
        pipe.InitBuffer(inputQueue, 1, INPUT_BYTES);
        pipe.InitBuffer(outputQueue, 1, OUTPUT_BYTES);
        pipe.InitBuffer(gatherBuf, GATHER_BYTES);
        pipe.InitBuffer(offsetBuf, OFFSET_BYTES);
    }

    // Vector replacement for the old scalar Sum9: accumulate three width taps
    // from each of three adjacent input rows.
    __aicore__ inline void Sum9(const AscendC::LocalTensor<float>& acc,
                               const AscendC::LocalTensor<float>& gathered,
                               const AscendC::LocalTensor<float>& input,
                               const AscendC::LocalTensor<uint32_t>& offsets,
                               uint32_t rowBase)
    {
        for (uint32_t kh = 0; kh < 3; ++kh) {
            AscendC::LocalTensor<float> line = input[rowBase + kh * PADDED_W];
            for (uint32_t kw = 0; kw < 3; ++kw) {
                AscendC::Gather(gathered, line, offsets, kw * sizeof(float), TILE_W);
                AscendC::Add(acc, acc, gathered, TILE_W);
            }
        }
    }

    __aicore__ inline void CopyInput(const AscendC::LocalTensor<float>& input,
                                    uint64_t xBaseNC, int32_t dstart, int32_t hstart,
                                    uint64_t hwIn)
    {
        AscendC::Duplicate(input, 0.0f, INPUT_ELEMS);
        AscendC::PipeBarrier<PIPE_V>();
        event_t vToMte2 = static_cast<event_t>(GetTPipePtr()->FetchEventID(AscendC::HardEvent::V_MTE2));
        AscendC::SetFlag<AscendC::HardEvent::V_MTE2>(vToMte2);
        AscendC::WaitFlag<AscendC::HardEvent::V_MTE2>(vToMte2);

        AscendC::DataCopyPadExtParams<float> padParams(true, 1, 7, 0.0f);
        if (dstart >= 0 && dstart + 3 <= static_cast<int32_t>(d_in) &&
            hstart >= 0 && hstart + 3 <= static_cast<int32_t>(h_in)) {
            // Three legal H rows are one batch; repeat for the three D planes.
            AscendC::DataCopyExtParams copyParams(3, w_in * sizeof(float), 0, 0, 0);
            for (uint32_t kd = 0; kd < 3; ++kd) {
                uint64_t gmOffset = xBaseNC + static_cast<uint64_t>(dstart + kd) * hwIn +
                                    static_cast<uint64_t>(hstart) * w_in;
                AscendC::DataCopyPad(input[kd * 3 * PADDED_W], xGm[gmOffset], copyParams, padParams);
            }
            return;
        }

        AscendC::DataCopyExtParams rowParams(1, w_in * sizeof(float), 0, 0, 0);
        for (int32_t kd = 0; kd < 3; ++kd) {
            int32_t di = dstart + kd;
            if (di < 0 || di >= static_cast<int32_t>(d_in)) continue;
            for (int32_t kh = 0; kh < 3; ++kh) {
                int32_t hi = hstart + kh;
                if (hi < 0 || hi >= static_cast<int32_t>(h_in)) continue;
                uint64_t gmOffset = xBaseNC + static_cast<uint64_t>(di) * hwIn +
                                    static_cast<uint64_t>(hi) * w_in;
                uint32_t ubOffset = static_cast<uint32_t>(kd * 3 + kh) * PADDED_W;
                AscendC::DataCopyPad(input[ubOffset], xGm[gmOffset], rowParams, padParams);
            }
        }
    }

    __aicore__ inline void Process()
    {
        constexpr int32_t S = 2;
        constexpr int32_t P = 1;
        const uint32_t coreId = AscendC::GetBlockIdx();
        const uint32_t startRow = coreId * rowsPerBlock;
        if (startRow >= rows) return;
        uint32_t endRow = startRow + rowsPerBlock;
        if (endRow > rows) endRow = rows;

        const uint64_t hwIn = static_cast<uint64_t>(h_in) * w_in;
        const uint64_t dhwIn = static_cast<uint64_t>(d_in) * hwIn;
        const uint64_t hwOut = static_cast<uint64_t>(h_out) * w_out;
        const uint64_t dhwOut = static_cast<uint64_t>(d_out) * hwOut;

        for (uint32_t row = startRow; row < endRow; ++row) {
            uint32_t oh = row % h_out;
            uint32_t t0 = row / h_out;
            uint32_t od = t0 % d_out;
            uint32_t t1 = t0 / d_out;
            uint32_t ci = t1 % c;
            uint32_t ni = t1 / c;
            uint64_t xBaseNC = (static_cast<uint64_t>(ni) * c + ci) * dhwIn;
            uint64_t yRowBase = (static_cast<uint64_t>(ni) * c + ci) * dhwOut +
                                static_cast<uint64_t>(od) * hwOut + static_cast<uint64_t>(oh) * w_out;

            AscendC::LocalTensor<float> input = inputQueue.AllocTensor<float>();
            CopyInput(input, xBaseNC, static_cast<int32_t>(od) * S - P,
                      static_cast<int32_t>(oh) * S - P, hwIn);
            inputQueue.EnQue(input);
            input = inputQueue.DeQue<float>();

            AscendC::LocalTensor<float> output = outputQueue.AllocTensor<float>();
            AscendC::LocalTensor<float> gathered = gatherBuf.Get<float>();
            AscendC::LocalTensor<int32_t> signedOffsets = offsetBuf.Get<int32_t>();
            AscendC::CreateVecIndex(signedOffsets, static_cast<int32_t>(0), TILE_W);
            AscendC::ShiftLeft(signedOffsets, signedOffsets, static_cast<int32_t>(3), TILE_W);
            AscendC::LocalTensor<uint32_t> offsets = signedOffsets.ReinterpretCast<uint32_t>();
            AscendC::Duplicate(output, 0.0f, TILE_W);
            for (uint32_t kd = 0; kd < 3; ++kd) {
                Sum9(output, gathered, input, offsets, kd * 3 * PADDED_W);
            }
            AscendC::Muls(output, output, 1.0f / 27.0f, TILE_W);
            inputQueue.FreeTensor(input);

            outputQueue.EnQue(output);
            output = outputQueue.DeQue<float>();
            AscendC::DataCopyExtParams outParams(1, w_out * sizeof(float), 0, 0, 0);
            AscendC::DataCopyPad(yGm[yRowBase], output, outParams);
            outputQueue.FreeTensor(output);
        }
    }

private:
    static constexpr uint32_t TILE_W = 128;
    static constexpr uint32_t PADDED_W = 264;
    static constexpr uint32_t INPUT_ELEMS = 3 * 3 * PADDED_W;
    static constexpr uint32_t INPUT_BYTES = INPUT_ELEMS * sizeof(float);
    static constexpr uint32_t OUTPUT_BYTES = TILE_W * sizeof(float);
    static constexpr uint32_t GATHER_BYTES = TILE_W * sizeof(float);
    static constexpr uint32_t OFFSET_BYTES = TILE_W * sizeof(uint32_t);

    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, 1> inputQueue;
    AscendC::TQue<AscendC::TPosition::VECOUT, 1> outputQueue;
    AscendC::TBuf<AscendC::TPosition::VECCALC> gatherBuf;
    AscendC::TBuf<AscendC::TPosition::VECCALC> offsetBuf;
    AscendC::GlobalTensor<float> xGm;
    AscendC::GlobalTensor<float> yGm;
    uint32_t n, c, d_in, h_in, w_in, d_out, h_out, w_out, rows, rowsPerBlock;
};

extern "C" __global__ __aicore__ void average_pooling3d_custom(
