                               uint32_t rows, uint32_t ow, uint32_t oh,
                               uint32_t tileOw, uint32_t owTiles, uint32_t tasks)
    {
        xGm.SetGlobalBuffer((__gm__ float*)x);
        wGm.SetGlobalBuffer((__gm__ float*)weight);
        yGm.SetGlobalBuffer((__gm__ float*)y);

        rows_ = rows;
        OW_ = ow;
        OH_ = oh;
        tileOw_ = tileOw;
        owTiles_ = owTiles;
        tasks_ = tasks;

        pipe_.InitBuffer(inputQueue_, 4, TILE_BYTES);
        pipe_.InitBuffer(outputQueue_, 1, TILE_BYTES);
        pipe_.InitBuffer(calcBuffer_, TILE_BYTES);
    }

    __aicore__ inline void Process()
    {
        // Specialized constants for benchmark.
        constexpr uint32_t N_ = 64;
        constexpr uint32_t C_ = 8;
        constexpr uint32_t H_ = 512;
        constexpr uint32_t W_ = 512;
        constexpr uint32_t KH_ = 3;

        const uint32_t coreId  = (uint32_t)AscendC::GetBlockIdx();
        const uint32_t coreNum = (uint32_t)AscendC::GetBlockNum();

        const uint32_t tasksPerCore = (tasks_ + coreNum - 1U) / coreNum;
        uint32_t taskStart = coreId * tasksPerCore;
        uint32_t taskEnd = taskStart + tasksPerCore;
        if (taskEnd > tasks_) taskEnd = tasks_;

        const uint32_t OW = OW_;
        const uint32_t OH = OH_;
        for (uint32_t task = taskStart; task < taskEnd; ++task) {
            const uint32_t c = task % C_;
            const uint32_t n = task / C_;

            const uint32_t wBase = c * KH_;
            const float w0 = wGm.GetValue(wBase + 0U);
            const float w1 = wGm.GetValue(wBase + 1U);
            const float w2 = wGm.GetValue(wBase + 2U);

            const uint32_t xNcBase = (n * C_ + c) * (H_ * W_);
            const uint32_t yNcBase = (n * C_ + c) * (OH * OW);

            AscendC::LocalTensor<float> row0 = inputQueue_.AllocTensor<float>();
            AscendC::DataCopy(row0, xGm[xNcBase], TILE_ELEMS);
            inputQueue_.EnQue(row0);
            row0 = inputQueue_.DeQue<float>();

            AscendC::LocalTensor<float> row1 = inputQueue_.AllocTensor<float>();
            AscendC::DataCopy(row1, xGm[xNcBase + W_], TILE_ELEMS);
            inputQueue_.EnQue(row1);
            row1 = inputQueue_.DeQue<float>();

            AscendC::LocalTensor<float> row2 = inputQueue_.AllocTensor<float>();
            AscendC::DataCopy(row2, xGm[xNcBase + 2U * W_], TILE_ELEMS);
            inputQueue_.EnQue(row2);
            row2 = inputQueue_.DeQue<float>();

            AscendC::LocalTensor<float> temp = calcBuffer_.Get<float>();

            for (uint32_t oh = 0; oh < OH; ++oh) {
                AscendC::LocalTensor<float> nextRow;
                const bool hasNextRow = (oh + KH_ < H_);

                AscendC::LocalTensor<float> output = outputQueue_.AllocTensor<float>();
                AscendC::Muls(output, row0, w0, static_cast<int32_t>(TILE_ELEMS));
                AscendC::Muls(temp, row1, w1, static_cast<int32_t>(TILE_ELEMS));
                AscendC::Add(output, output, temp, static_cast<int32_t>(TILE_ELEMS));
                AscendC::Muls(temp, row2, w2, static_cast<int32_t>(TILE_ELEMS));
                AscendC::Add(output, output, temp, static_cast<int32_t>(TILE_ELEMS));
                outputQueue_.EnQue(output);

                output = outputQueue_.DeQue<float>();
                AscendC::DataCopy(yGm[yNcBase + oh * OW], output, TILE_ELEMS);
                outputQueue_.FreeTensor(output);

                inputQueue_.FreeTensor(row0);
                if (hasNextRow) {
                    nextRow = inputQueue_.AllocTensor<float>();
                    AscendC::DataCopy(nextRow, xGm[xNcBase + (oh + KH_) * W_], TILE_ELEMS);
                    inputQueue_.EnQue(nextRow);
                    nextRow = inputQueue_.DeQue<float>();
                    row0 = row1;
                    row1 = row2;
                    row2 = nextRow;
                }

            }

            inputQueue_.FreeTensor(row1);
            inputQueue_.FreeTensor(row2);
        }
    }

private:
