    AscendC::TQue<AscendC::QuePosition::VECIN, 1> inputQueue_;
    AscendC::TQue<AscendC::QuePosition::VECOUT, 1> outputQueue_;
    AscendC::TBuf<AscendC::QuePosition::VECCALC> calcBuffer_;

    uint32_t rows_{0};
    uint32_t OW_{0};
    uint32_t OH_{0};
    uint32_t tileOw_{512};
    uint32_t owTiles_{0};
    uint32_t tasks_{0};
};

