#include "kernel_operator.h"

class KernelConvDepthwise2dSquareSquare {
public:
    __aicore__ inline KernelConvDepthwise2dSquareSquare() {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR w, GM_ADDR y,
                               uint32_t rows, uint32_t ow,
                               uint32_t H, uint32_t W, uint32_t C, uint32_t OH)
    {
        xGm.SetGlobalBuffer((__gm__ float*)x);
        wGm.SetGlobalBuffer((__gm__ float*)w);
        yGm.SetGlobalBuffer((__gm__ float*)y);
        rows_ = rows;
        ow_ = ow;
        H_ = H;
        W_ = W;
        C_ = C;
        OH_ = OH;

        pipe.InitBuffer(xQueue, 1, INPUT_BUFFER_BYTES);
        pipe.InitBuffer(weightQueue, 1, WEIGHT_BUFFER_BYTES);
        pipe.InitBuffer(yQueue, 1, OUTPUT_BUFFER_BYTES);
        pipe.InitBuffer(calcBuf, CALC_BUFFER_BYTES);
        pipe.InitBuffer(indexBuf, INDEX_BUFFER_BYTES);
    }

    __aicore__ inline void Process()
    {
        const uint32_t coreId = (uint32_t)AscendC::GetBlockIdx();
        const uint32_t coreNum = (uint32_t)AscendC::GetBlockNum();
        const uint32_t totalNc = rows_ / OH_;
        AscendC::LocalTensor<uint32_t> indexLocal = indexBuf.Get<uint32_t>();
        for (uint32_t i = 0; i < GATHER_LANES; ++i) {
            indexLocal.SetValue(i, static_cast<uint32_t>(i * sizeof(float)));
        }
        const int32_t indexReady =
            static_cast<int32_t>(pipe.FetchEventID<AscendC::HardEvent::S_V>());
        AscendC::SetFlag<AscendC::HardEvent::S_V>(indexReady);
        AscendC::WaitFlag<AscendC::HardEvent::S_V>(indexReady);

        for (uint32_t nc = coreId; nc < totalNc; nc += coreNum) {
            const uint32_t c = nc % C_;
            const uint32_t xNcBase = nc * H_ * W_;
            const uint32_t yNcBase = nc * OH_ * ow_;

            AscendC::LocalTensor<float> weightLocal = weightQueue.AllocTensor<float>();
            AscendC::DataCopyExtParams weightCopy{1, 9u * sizeof(float), 0, 0, 0};
            AscendC::DataCopyPadExtParams<float> noPad{false, 0, 0, 0.0f};
            AscendC::DataCopyPad(weightLocal, wGm[c * 9u], weightCopy, noPad);
            weightQueue.EnQue(weightLocal);
            weightLocal = weightQueue.DeQue<float>();

            const float w00 = weightLocal.GetValue(0u);
            const float w01 = weightLocal.GetValue(1u);
            const float w02 = weightLocal.GetValue(2u);
            const float w10 = weightLocal.GetValue(3u);
            const float w11 = weightLocal.GetValue(4u);
            const float w12 = weightLocal.GetValue(5u);
            const float w20 = weightLocal.GetValue(6u);
            const float w21 = weightLocal.GetValue(7u);
            const float w22 = weightLocal.GetValue(8u);

            for (uint32_t ohStart = 0; ohStart < OH_; ohStart += TILE_OH) {
                uint32_t validOh = OH_ - ohStart;
                if (validOh > TILE_OH) validOh = TILE_OH;
                const uint32_t inputElems = (validOh + 2u) * INPUT_STRIDE;

                AscendC::LocalTensor<float> xLocal = xQueue.AllocTensor<float>();
                AscendC::DataCopyExtParams xCopy{
                    1, static_cast<uint32_t>(inputElems * sizeof(float)), 0, 0, 0};
                AscendC::DataCopyPad(xLocal, xGm[xNcBase + ohStart * W_], xCopy, noPad);
                xQueue.EnQue(xLocal);
                xLocal = xQueue.DeQue<float>();

                AscendC::LocalTensor<float> yLocal = yQueue.AllocTensor<float>();
                AscendC::LocalTensor<float> tmpLocal = calcBuf.Get<float>();

                for (uint32_t tileRow = 0; tileRow < validOh; ++tileRow) {
                    const uint32_t in0 = tileRow * INPUT_STRIDE;
                    const uint32_t in1 = in0 + INPUT_STRIDE;
                    const uint32_t in2 = in1 + INPUT_STRIDE;
                    const uint32_t out = tileRow * OUTPUT_STRIDE;
                    AscendC::LocalTensor<float> outRow = yLocal[out];

                    AscendC::Muls(outRow, xLocal[in0], w00, (int32_t)OUTPUT_WIDTH);
                    GatherAccumulate(outRow, tmpLocal, xLocal, indexLocal, in0 + 1u, w01);
                    GatherAccumulate(outRow, tmpLocal, xLocal, indexLocal, in0 + 2u, w02);
                    Accumulate(outRow, tmpLocal, xLocal[in1], w10);
                    GatherAccumulate(outRow, tmpLocal, xLocal, indexLocal, in1 + 1u, w11);
                    GatherAccumulate(outRow, tmpLocal, xLocal, indexLocal, in1 + 2u, w12);
                    Accumulate(outRow, tmpLocal, xLocal[in2], w20);
                    GatherAccumulate(outRow, tmpLocal, xLocal, indexLocal, in2 + 1u, w21);
                    GatherAccumulate(outRow, tmpLocal, xLocal, indexLocal, in2 + 2u, w22);
                }

                yQueue.EnQue(yLocal);
                yLocal = yQueue.DeQue<float>();
                AscendC::DataCopyExtParams yCopy{1, OUTPUT_WIDTH * sizeof(float), 0, 0, 0};
                for (uint32_t tileRow = 0; tileRow < validOh; ++tileRow) {
                    const uint32_t gmOffset = yNcBase + (ohStart + tileRow) * ow_;
                    AscendC::DataCopyPad(yGm[gmOffset], yLocal[tileRow * OUTPUT_STRIDE], yCopy);
                }

                yQueue.FreeTensor(yLocal);
                xQueue.FreeTensor(xLocal);
            }
            weightQueue.FreeTensor(weightLocal);
        }
    }

private:
    __aicore__ inline void Accumulate(const AscendC::LocalTensor<float>& dst,
                                      const AscendC::LocalTensor<float>& tmp,
                                      const AscendC::LocalTensor<float>& src,
                                      float weight)
    {
        AscendC::Muls(tmp, src, weight, (int32_t)OUTPUT_WIDTH);
        AscendC::Add(dst, dst, tmp, (int32_t)OUTPUT_WIDTH);
    }

    __aicore__ inline void GatherAccumulate(const AscendC::LocalTensor<float>& dst,
                                            const AscendC::LocalTensor<float>& tmp,
                                            const AscendC::LocalTensor<float>& src,
                                            const AscendC::LocalTensor<uint32_t>& index,
                                            uint32_t srcElemOffset, float weight)
    {
        for (uint32_t offset = 0; offset < OUTPUT_WIDTH; offset += GATHER_LANES) {
            uint32_t count = OUTPUT_WIDTH - offset;
            if (count > GATHER_LANES) count = GATHER_LANES;
            const uint32_t srcBaseBytes = (srcElemOffset + offset) * sizeof(float);
            AscendC::Gather(tmp[offset], src, index, srcBaseBytes, count);
        }
        AscendC::Muls(tmp, tmp, weight, (int32_t)OUTPUT_WIDTH);
        AscendC::Add(dst, dst, tmp, (int32_t)OUTPUT_WIDTH);
    }

    static constexpr uint32_t TILE_OH = 46u;
    static constexpr uint32_t INPUT_STRIDE = 512u;
    static constexpr uint32_t OUTPUT_WIDTH = 510u;
    static constexpr uint32_t OUTPUT_STRIDE = 512u;
    static constexpr uint32_t GATHER_LANES = 64u;
    static constexpr uint32_t INPUT_BUFFER_BYTES = (TILE_OH + 2u) * INPUT_STRIDE * sizeof(float);
    static constexpr uint32_t OUTPUT_BUFFER_BYTES = TILE_OH * OUTPUT_STRIDE * sizeof(float);
    static constexpr uint32_t WEIGHT_BUFFER_BYTES = 32u * sizeof(float);
    static constexpr uint32_t CALC_BUFFER_BYTES = OUTPUT_STRIDE * sizeof(float);
    static constexpr uint32_t INDEX_BUFFER_BYTES = GATHER_LANES * sizeof(uint32_t);

    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, 1> xQueue;
    AscendC::TQue<AscendC::TPosition::VECIN, 1> weightQueue;
    AscendC::TQue<AscendC::TPosition::VECOUT, 1> yQueue;
    AscendC::TBuf<AscendC::TPosition::VECCALC> calcBuf;
    AscendC::TBuf<AscendC::TPosition::VECCALC> indexBuf;
    AscendC::GlobalTensor<float> xGm;
    AscendC::GlobalTensor<float> wGm;
    AscendC::GlobalTensor<float> yGm;

    uint32_t rows_{0};
    uint32_t ow_{0};
    uint32_t H_{0};
    uint32_t W_{0};
    uint32_t C_{0};
    uint32_t OH_{0};
};

extern "C" __global__ __aicore__ void conv_depthwise2d_square_input_square_kernel_custom(
    GM_ADDR x, GM_ADDR weight, GM_ADDR y, GM_ADDR workspace, GM_ADDR tiling)
{
    (void)workspace;
    GET_TILING_DATA(tiling_data, tiling);
    KernelConvDepthwise2dSquareSquare op;
    op.Init(x, weight, y,
            tiling_data.rows, tiling_data.ow,
            tiling_data.h, tiling_data.w, tiling_data.c, tiling_data.oh);
    op.Process();
}

