#include "kernel_operator.h"

// Pointwise Conv2d (1x1) specialized:
// x: [16, 64, 1024, 1024] NCHW, float32 contiguous
// w: [128, 64, 1, 1]     OIHW, float32 contiguous
// y: [16, 128, 1024, 1024] NCHW
//
// Each task computes one contiguous 312-position W tile for every COUT.
// The ci loop is outside the output-channel loop so each input tile is loaded
// once, consumed by all 128 channels, and accumulated entirely in UB.

class KernelConvPointwise2dCustom_WT16_WG2_COB8 {
public:
    __aicore__ inline KernelConvPointwise2dCustom_WT16_WG2_COB8() {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR w, GM_ADDR y,
                               uint32_t n, uint32_t cin, uint32_t cout,
                               uint32_t h, uint32_t w_in,
                               uint32_t w_tile, uint32_t w_group,
                               uint32_t w_group_len, uint32_t w_groups,
                               uint32_t tasks)
    {
        xGm.SetGlobalBuffer((__gm__ float*)x);
        wGm.SetGlobalBuffer((__gm__ float*)w);
        yGm.SetGlobalBuffer((__gm__ float*)y);

        n_ = n; cin_ = cin; cout_ = cout;
        h_ = h; w_ = w_in;

        wTile_ = w_tile;
        wGroup_ = w_group;
        wGroupLen_ = w_group_len;
        wGroups_ = w_groups;
        tasks_ = tasks;

        // UB bytes: weights 32768 + input 1248 + accumulators 159744 = 193760.
        pipe_.InitBuffer(wBuf_, cout_ * cin_ * sizeof(float));
        pipe_.InitBuffer(xTileBuf_, wTile_ * sizeof(float));
        pipe_.InitBuffer(accBuf_, cout_ * wTile_ * sizeof(float));
    }

    __aicore__ inline void Process()
    {
        const uint32_t coreId = (uint32_t)AscendC::GetBlockIdx();
        const uint32_t coreNum = (uint32_t)AscendC::GetBlockNum();

        // Cache weights to UB once per core.
        AscendC::LocalTensor<float> wLocal = wBuf_.Get<float>(0);
        AscendC::DataCopy(wLocal, wGm, cout_ * cin_);
        event_t weightReady = static_cast<event_t>(pipe_.FetchEventID(AscendC::HardEvent::MTE2_S));
        AscendC::SetFlag<AscendC::HardEvent::MTE2_S>(weightReady);
        AscendC::WaitFlag<AscendC::HardEvent::MTE2_S>(weightReady);

        const uint32_t tasksPerCore = (tasks_ + coreNum - 1U) / coreNum;
        uint32_t tStart = coreId * tasksPerCore;
        uint32_t tEnd = tStart + tasksPerCore;
        if (tEnd > tasks_) tEnd = tasks_;
        if (tStart >= tEnd) return;

        AscendC::LocalTensor<float> xTile = xTileBuf_.Get<float>(0);
        AscendC::LocalTensor<float> accum = accBuf_.Get<float>(0);

        for (uint32_t t = tStart; t < tEnd; ++t) {
            uint32_t tmp = t;
            const uint32_t wGroupIdx = tmp % wGroups_;
            tmp /= wGroups_;
            const uint32_t hIdx = tmp % h_;
            const uint32_t nIdx = tmp / h_;
            if (nIdx >= n_) continue;

            const uint32_t wStart = wGroupIdx * wGroupLen_;
            if (wStart >= w_) continue;
            uint32_t validLen = wTile_;
            if (wStart + validLen > w_) validLen = w_ - wStart;

            const uint32_t xNHBase = (nIdx * cin_ * h_ + hIdx) * w_;   // x[n,0,h,0]
            const uint32_t yNHBase = (nIdx * cout_ * h_ + hIdx) * w_;  // y[n,0,h,0]

            AscendC::Duplicate(accum, 0.0f, static_cast<int32_t>(cout_ * wTile_));

            for (uint32_t ci = 0; ci < cin_; ++ci) {
                const uint32_t xBase = xNHBase + ci * h_ * w_ + wStart;
                AscendC::DataCopy(xTile, xGm[xBase], validLen);
                event_t inputReady = static_cast<event_t>(pipe_.FetchEventID(AscendC::HardEvent::MTE2_V));
                AscendC::SetFlag<AscendC::HardEvent::MTE2_V>(inputReady);
                AscendC::WaitFlag<AscendC::HardEvent::MTE2_V>(inputReady);

                for (uint32_t co = 0; co < cout_; ++co) {
                    const float weight = wLocal.GetValue(co * cin_ + ci);
                    AscendC::LocalTensor<float> accSlice = accum[co * wTile_];
                    AscendC::Axpy(accSlice, xTile, weight, static_cast<int32_t>(validLen));
                }

                event_t inputConsumed = static_cast<event_t>(pipe_.FetchEventID(AscendC::HardEvent::V_MTE2));
                AscendC::SetFlag<AscendC::HardEvent::V_MTE2>(inputConsumed);
                AscendC::WaitFlag<AscendC::HardEvent::V_MTE2>(inputConsumed);
            }

            event_t outputReady = static_cast<event_t>(pipe_.FetchEventID(AscendC::HardEvent::V_MTE3));
            AscendC::SetFlag<AscendC::HardEvent::V_MTE3>(outputReady);
            AscendC::WaitFlag<AscendC::HardEvent::V_MTE3>(outputReady);
            for (uint32_t co = 0; co < cout_; ++co) {
                const uint32_t yBase = yNHBase + co * h_ * w_ + wStart;
                AscendC::DataCopy(yGm[yBase], accum[co * wTile_], validLen);
            }
            event_t outputConsumed = static_cast<event_t>(pipe_.FetchEventID(AscendC::HardEvent::MTE3_V));
            AscendC::SetFlag<AscendC::HardEvent::MTE3_V>(outputConsumed);
            AscendC::WaitFlag<AscendC::HardEvent::MTE3_V>(outputConsumed);
        }
    }

private:
    AscendC::TPipe pipe_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> wBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> xTileBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> accBuf_;

    AscendC::GlobalTensor<float> xGm;
    AscendC::GlobalTensor<float> wGm;
    AscendC::GlobalTensor<float> yGm;

    uint32_t n_{0}, cin_{0}, cout_{0}, h_{0}, w_{0};
    uint32_t wTile_{0}, wGroup_{0}, wGroupLen_{0}, wGroups_{0}, tasks_{0};
};

extern "C" __global__ __aicore__ void conv_pointwise2d_custom(
    GM_ADDR x, GM_ADDR weight, GM_ADDR y, GM_ADDR workspace, GM_ADDR tiling)
{
    (void)workspace;
    GET_TILING_DATA(tiling_data, tiling);

    KernelConvPointwise2dCustom_WT16_WG2_COB8 op;
    op.Init(x, weight, y,
            tiling_data.n, tiling_data.cin, tiling_data.cout,
            tiling_data.h, tiling_data.w,
            tiling_data.w_tile, tiling_data.w_group,
            tiling_data.w_group_len, tiling_data.w_groups,
            tiling_data.tasks);
    op.Process();
}

