#include "kernel_operator.h"

class KernelConvStandard2dAsymSquareOwTiledFastPath {
public:
    __aicore__ inline KernelConvStandard2dAsymSquareOwTiledFastPath() {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR w, GM_ADDR y,
                               uint32_t rows, uint32_t ow,
                               uint32_t H, uint32_t W,
                               uint32_t CIN, uint32_t COUT, uint32_t OH,
                               uint32_t tileOw, uint32_t owTiles, uint32_t tasks)
    {
        xGm.SetGlobalBuffer((__gm__ float*)x);
        wGm.SetGlobalBuffer((__gm__ float*)w);
        yGm.SetGlobalBuffer((__gm__ float*)y);

        rows_ = rows;
        ow_ = ow;
        H_ = H;
        W_ = W;
        CIN_ = CIN;
        COUT_ = COUT;
        OH_ = OH;
        tileOw_ = tileOw;
        owTiles_ = owTiles;
        tasks_ = tasks;

        pipe.InitBuffer(inputQueue, 1, INPUT_BYTES);
        pipe.InitBuffer(weightQueue, 1, WEIGHT_BYTES);
        pipe.InitBuffer(outputQueue, 1, VECTOR_BYTES);
        pipe.InitBuffer(accBuffer, VECTOR_BYTES);
        pipe.InitBuffer(tempBuffer, VECTOR_BYTES);
    }

    __aicore__ inline void Process()
    {
        const uint32_t coreId = (uint32_t)AscendC::GetBlockIdx();
        const uint32_t coreNum = (uint32_t)AscendC::GetBlockNum();

        const uint32_t tasksPerCore = (tasks_ + coreNum - 1U) / coreNum;
        uint32_t taskStart = coreId * tasksPerCore;
        uint32_t taskEnd = taskStart + tasksPerCore;
        if (taskEnd > tasks_) taskEnd = tasks_;

        const uint32_t ow = ow_;
        const uint32_t W = W_;
        const uint32_t H = H_;
        const uint32_t CIN = CIN_;
        const uint32_t COUT = COUT_;
        const uint32_t OH = OH_;
        const uint32_t owTiles = owTiles_;

        for (uint32_t task = taskStart; task < taskEnd; ++task) {
            const uint32_t row = task / owTiles;
            const uint32_t ow0 = 0;

            uint32_t tmp = row;
            const uint32_t oh = tmp % OH;
            tmp /= OH;
            const uint32_t co = tmp % COUT;
            const uint32_t n  = tmp / COUT;

            const uint32_t yBase = ((n * COUT + co) * OH + oh) * ow + ow0;

            const uint32_t ih0 = oh;
            const uint32_t wCoBase = co * (CIN * 9U);
            const uint32_t xNBase = n * (CIN * H * W);

            AscendC::LocalTensor<float> weightLocal = weightQueue.AllocTensor<float>();
            const AscendC::DataCopyExtParams weightCopy{1, WEIGHT_BYTES, 0, 0, 0};
            const AscendC::DataCopyPadExtParams<float> noPad{};
            AscendC::DataCopyPad(weightLocal, wGm[wCoBase], weightCopy, noPad);
            weightQueue.EnQue(weightLocal);
            weightLocal = weightQueue.DeQue<float>();

            AscendC::LocalTensor<float> accLocal = accBuffer.Get<float>();
            AscendC::LocalTensor<float> tempLocal = tempBuffer.Get<float>();
            AscendC::Duplicate(accLocal, 0.0f, VECTOR_ELEMS);

            for (uint32_t ci = 0; ci < CIN; ++ci) {
                const uint32_t xBase = xNBase + ci * (H * W) + ih0 * W;
                AscendC::LocalTensor<float> inputLocal = inputQueue.AllocTensor<float>();
                const AscendC::DataCopyExtParams inputWindowCopy{1, OUTPUT_BYTES, 0, 0, 0};
                for (uint32_t kh = 0; kh < 3U; ++kh) {
                    for (uint32_t kw = 0; kw < 3U; ++kw) {
                        const uint32_t window = (kh * 3U + kw) * VECTOR_ELEMS;
                        AscendC::DataCopyPad(inputLocal[window], xGm[xBase + kh * W + kw],
                                            inputWindowCopy, noPad);
                    }
                }
                inputQueue.EnQue(inputLocal);
                inputLocal = inputQueue.DeQue<float>();

                const uint32_t wBase = ci * 9U;
                for (uint32_t kh = 0; kh < 3U; ++kh) {
                    for (uint32_t kw = 0; kw < 3U; ++kw) {
                        const float weightValue = weightLocal.GetValue(wBase + kh * 3U + kw);
                        const uint32_t window = (kh * 3U + kw) * VECTOR_ELEMS;
                        AscendC::Muls(tempLocal, inputLocal[window], weightValue, ow);
                        AscendC::Add(accLocal, accLocal, tempLocal, ow);
                    }
                }
                inputQueue.FreeTensor(inputLocal);
            }
            weightQueue.FreeTensor(weightLocal);

            AscendC::LocalTensor<float> outputLocal = outputQueue.AllocTensor<float>();
            AscendC::Duplicate(tempLocal, 0.0f, VECTOR_ELEMS);
            AscendC::Add(outputLocal, accLocal, tempLocal, ow);
            outputQueue.EnQue(outputLocal);
            outputLocal = outputQueue.DeQue<float>();
            const AscendC::DataCopyExtParams outputCopy{1, OUTPUT_BYTES, 0, 0, 0};
            AscendC::DataCopyPad(yGm[yBase], outputLocal, outputCopy);
            outputQueue.FreeTensor(outputLocal);
        }
    }

private:
    static constexpr uint32_t VECTOR_ELEMS = 1024U;
    static constexpr uint32_t ROW_BYTES = VECTOR_ELEMS * sizeof(float);
    static constexpr uint32_t INPUT_BYTES = 9U * ROW_BYTES;
    static constexpr uint32_t WEIGHT_BYTES = 64U * 9U * sizeof(float);
    static constexpr uint32_t VECTOR_BYTES = VECTOR_ELEMS * sizeof(float);
    static constexpr uint32_t OUTPUT_BYTES = 1022U * sizeof(float);

    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, 1> inputQueue;
    AscendC::TQue<AscendC::TPosition::VECIN, 1> weightQueue;
    AscendC::TQue<AscendC::TPosition::VECOUT, 1> outputQueue;
    AscendC::TBuf<AscendC::TPosition::VECCALC> accBuffer;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tempBuffer;

    AscendC::GlobalTensor<float> xGm;
    AscendC::GlobalTensor<float> wGm;
    AscendC::GlobalTensor<float> yGm;

    uint32_t rows_{0};
    uint32_t ow_{0};
    uint32_t H_{0};
    uint32_t W_{0};
    uint32_t CIN_{0};
    uint32_t COUT_{0};
    uint32_t OH_{0};
    uint32_t tileOw_{16};
    uint32_t owTiles_{0};
    uint32_t tasks_{0};
};

