        wo_ = wo;
        H_ = H;
        W_ = W;
        CIN_ = CIN;
        COUT_ = COUT;
        HO_ = HO;
        tileWo_ = tileWo;
        woTiles_ = woTiles;
        tasks_ = tasks;

        pipe_.InitBuffer(xQueue_, 1, INPUT_WINDOW_ELEMS * sizeof(float));
        pipe_.InitBuffer(weightQueue_, 1, WEIGHT_ELEMS * sizeof(float));
        pipe_.InitBuffer(outputQueue_, 1, ALIGNED_OUTPUT_ELEMS * sizeof(float));
        pipe_.InitBuffer(tmpBuf_, ALIGNED_OUTPUT_ELEMS * sizeof(float));
    }

