class KernelConvStandard2dSquareInputAsym5x9WoTiledSliding {
public:
    __aicore__ inline KernelConvStandard2dSquareInputAsym5x9WoTiledSliding() {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR w, GM_ADDR y,
                               uint32_t rows, uint32_t wo,
                               uint32_t H, uint32_t W,
                               uint32_t CIN, uint32_t COUT, uint32_t HO,
                               uint32_t tileWo, uint32_t woTiles, uint32_t tasks)
    {
        xGm.SetGlobalBuffer((__gm__ float*)x);
        wGm.SetGlobalBuffer((__gm__ float*)w);
        yGm.SetGlobalBuffer((__gm__ float*)y);

        rows_ = rows;
        wo_ = wo;
        H_ = H;
        W_ = W;
        CIN_ = CIN;
        COUT_ = COUT;
        HO_ = HO;
        tileWo_ = tileWo;
        woTiles_ = woTiles;
        tasks_ = tasks;

        pipe_.InitBuffer(xQueue_, 1, INPUT_CHUNK_ELEMS * sizeof(float));
        pipe_.InitBuffer(weightQueue_, 1, WEIGHT_ELEMS * sizeof(float));
        pipe_.InitBuffer(outputQueue_, 1, ALIGNED_OUTPUT_ELEMS * sizeof(float));
        pipe_.InitBuffer(tmpBuf_, 2 * ALIGNED_OUTPUT_ELEMS * sizeof(float));
    }

    __aicore__ inline void Process()
    {
        const uint32_t coreId = (uint32_t)AscendC::GetBlockIdx();
        const uint32_t coreNum = (uint32_t)AscendC::GetBlockNum();

        const uint32_t tasksPerCore = (tasks_ + coreNum - 1U) / coreNum;
        uint32_t taskStart = coreId * tasksPerCore;
        uint32_t taskEnd = taskStart + tasksPerCore;
        if (taskEnd > tasks_) taskEnd = tasks_;

        constexpr uint32_t KH = 5;
        constexpr uint32_t KW = 9;

        const uint32_t wo = wo_;
        const uint32_t W = W_;
        const uint32_t H = H_;
        const uint32_t CIN = CIN_;
        const uint32_t COUT = COUT_;
        const uint32_t HO = HO_;
        AscendC::LocalTensor<float> window = tmpBuf_.Get<float>();
        AscendC::LocalTensor<int32_t> signedOffsets =
            tmpBuf_.Get<int32_t>()[ALIGNED_OUTPUT_ELEMS];
        AscendC::CreateVecIndex(signedOffsets, static_cast<int32_t>(0), OUTPUT_ELEMS);
        AscendC::Muls(signedOffsets, signedOffsets, static_cast<int32_t>(sizeof(float)),
                      static_cast<int32_t>(OUTPUT_ELEMS));
        AscendC::LocalTensor<uint32_t> offsets = signedOffsets.ReinterpretCast<uint32_t>();

        uint32_t task = taskStart;
        while (task < taskEnd) {
            uint32_t group = task / HO;
            const uint32_t co = group % COUT;
            const uint32_t n = group / COUT;
            uint32_t groupEnd = (group + 1U) * HO;
            if (groupEnd > taskEnd) groupEnd = taskEnd;

            const uint32_t wCoBase = co * WEIGHT_ELEMS;
            AscendC::LocalTensor<float> weights = weightQueue_.AllocTensor<float>();
            AscendC::DataCopy(weights, wGm[wCoBase], WEIGHT_ELEMS);
            weightQueue_.EnQue(weights);
            weights = weightQueue_.DeQue<float>();

            for (; task < groupEnd; ++task) {
                const uint32_t ho = task - group * HO;
                const uint32_t yBase = ((n * COUT + co) * HO + ho) * wo;
                const uint32_t xNBase = n * (CIN * H * W);

                AscendC::LocalTensor<float> output = outputQueue_.AllocTensor<float>();
                AscendC::Duplicate(output, 0.0f, static_cast<int32_t>(ALIGNED_OUTPUT_ELEMS));

                for (uint32_t ciBase = 0; ciBase < CIN; ciBase += INPUT_CHUNK_CI) {
                    uint32_t chunkCi = CIN - ciBase;
                    if (chunkCi > INPUT_CHUNK_CI) chunkCi = INPUT_CHUNK_CI;
                    AscendC::LocalTensor<float> input = xQueue_.AllocTensor<float>();
                    for (uint32_t ciOffset = 0; ciOffset < chunkCi; ++ciOffset) {
                        const uint32_t ci = ciBase + ciOffset;
                        const uint32_t xNcBase = xNBase + ci * (H * W);
#pragma unroll
                        for (uint32_t kh = 0; kh < KH; ++kh) {
                            const uint32_t xRowBase = xNcBase + (ho + kh) * W;
                            const uint32_t inputGroup = ciOffset * KH + kh;
                            const uint32_t inputOffset = inputGroup * ALIGNED_OUTPUT_ELEMS;
                            AscendC::DataCopy(input[inputOffset], xGm[xRowBase], INPUT_STRIP_ELEMS);
                        }
                    }
                    xQueue_.EnQue(input);
                    input = xQueue_.DeQue<float>();

                    for (uint32_t ciOffset = 0; ciOffset < chunkCi; ++ciOffset) {
                        const uint32_t ci = ciBase + ciOffset;
#pragma unroll
                        for (uint32_t kh = 0; kh < KH; ++kh) {
                            const uint32_t inputGroup = ciOffset * KH + kh;
                            const uint32_t inputOffset = inputGroup * ALIGNED_OUTPUT_ELEMS;
#pragma unroll
                            for (uint32_t kw = 0; kw < KW; ++kw) {
                                const uint32_t weightIndex = (ci * KH + kh) * KW + kw;
                                const float weightValue = weights.GetValue(weightIndex);
                                AscendC::Gather(window, input[inputOffset], offsets,
                                                kw * sizeof(float), OUTPUT_ELEMS);
                                AscendC::Axpy(output, window, weightValue,
                                              static_cast<int32_t>(OUTPUT_ELEMS));
                            }
                        }
                    }
                    xQueue_.FreeTensor(input);
                }

                outputQueue_.EnQue(output);
                output = outputQueue_.DeQue<float>();
                AscendC::DataCopy(yGm[yBase], output, OUTPUT_ELEMS);
                outputQueue_.FreeTensor(output);
            }
            weightQueue_.FreeTensor(weights);
        }
    }

private:
    static constexpr uint32_t OUTPUT_ELEMS = 504;
    static constexpr uint32_t ALIGNED_OUTPUT_ELEMS = 512;
    static constexpr uint32_t INPUT_STRIP_ELEMS = 512;
    static constexpr uint32_t INPUT_CHUNK_CI = 18;
    static constexpr uint32_t INPUT_CHUNK_ELEMS = INPUT_CHUNK_CI * 5 * INPUT_STRIP_ELEMS;
    static constexpr uint32_t WEIGHT_ELEMS = 32 * 5 * 9;

    AscendC::GlobalTensor<float> xGm;
    AscendC::GlobalTensor<float> wGm;
    AscendC::GlobalTensor<float> yGm;

    AscendC::TPipe pipe_;
    AscendC::TQue<AscendC::TPosition::VECIN, 1> xQueue_;
    AscendC::TQue<AscendC::TPosition::VECIN, 1> weightQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, 1> outputQueue_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf_;

    uint32_t rows_{0};
    uint32_t wo_{0};
    uint32_t H_{0};
    uint32_t W_{0};
    uint32_t CIN_{0};
    uint32_t COUT_{0};
    uint32_t HO_{0};
    uint32_t tileWo_{16};
    uint32_t woTiles_{0};
    uint32_t tasks_{0};
};

