#include "kernel_operator.h"

class KernelConvStandard2dSquareInputSquareK3x3OwTiledSliding {
public:
    __aicore__ inline KernelConvStandard2dSquareInputSquareK3x3OwTiledSliding() {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR w, GM_ADDR y,
                               uint32_t rows, uint32_t ow,
                               uint32_t H, uint32_t W,
                               uint32_t CIN, uint32_t COUT, uint32_t HO,
                               uint32_t tileOw, uint32_t owTiles, uint32_t tasks)
    {
        xGm.SetGlobalBuffer((__gm__ float*)x);
        wGm.SetGlobalBuffer((__gm__ float*)w);
        yGm.SetGlobalBuffer((__gm__ float*)y);

        rows_ = rows;
        ow_ = ow;
        H_ = H;
        W_ = W;
        CIN_ = CIN;
        COUT_ = COUT;
        HO_ = HO;
        tileOw_ = tileOw;
        owTiles_ = owTiles;
        tasks_ = tasks;

        pipe_.InitBuffer(xQueue_, 1, KW_PLANES * ALIGNED_TILE * sizeof(float));
        pipe_.InitBuffer(weightQueue_, 1, WEIGHT_ELEMS * sizeof(float));
        pipe_.InitBuffer(outputQueue_, 1, ALIGNED_TILE * sizeof(float));
        pipe_.InitBuffer(accBuf_, ALIGNED_TILE * sizeof(float));
        pipe_.InitBuffer(tmpBuf_, ALIGNED_TILE * sizeof(float));
    }

    __aicore__ inline void Process()
    {
        const uint32_t coreId = (uint32_t)AscendC::GetBlockIdx();
        const uint32_t coreNum = (uint32_t)AscendC::GetBlockNum();

        const uint32_t tasksPerCore = (tasks_ + coreNum - 1U) / coreNum;
        uint32_t taskStart = coreId * tasksPerCore;
        uint32_t taskEnd = taskStart + tasksPerCore;
        if (taskEnd > tasks_) taskEnd = tasks_;

        constexpr uint32_t KH = 3;
        constexpr uint32_t KW = 3;

        const uint32_t ow = ow_;
        const uint32_t W = W_;
        const uint32_t H = H_;
        const uint32_t CIN = CIN_;
        const uint32_t COUT = COUT_;
        const uint32_t HO = HO_;
        const uint32_t owTiles = owTiles_;

        for (uint32_t task = taskStart; task < taskEnd; ++task) {
            const uint32_t row = task / owTiles;
            const uint32_t ow0 = 0;

            uint32_t tmp = row;
            const uint32_t ho = tmp % HO;
            tmp /= HO;
            const uint32_t co = tmp % COUT;
            const uint32_t n  = tmp / COUT;

            const uint32_t yBase = ((n * COUT + co) * HO + ho) * ow + ow0;

            const uint32_t xNBase = n * (CIN * H * W);
            const uint32_t wCoBase = co * (CIN * KH * KW);

            AscendC::LocalTensor<float> weightLocal = weightQueue_.AllocTensor<float>();
            AscendC::DataCopy(weightLocal, wGm[wCoBase], WEIGHT_ELEMS);
            weightQueue_.EnQue(weightLocal);
            weightLocal = weightQueue_.DeQue<float>();

            AscendC::LocalTensor<float> accLocal = accBuf_.Get<float>();
            AscendC::LocalTensor<float> tmpLocal = tmpBuf_.Get<float>();
            AscendC::Duplicate(accLocal, 0.0f, ALIGNED_TILE);

            for (uint32_t ci = 0; ci < CIN; ++ci) {
                const uint32_t xNcBase = xNBase + ci * (H * W);
                const uint32_t wCociBase = wCoBase + ci * (KH * KW);

#pragma unroll
                for (uint32_t kh = 0; kh < KH; ++kh) {
                    const uint32_t ih = ho + kh;
                    const uint32_t xRowBase = xNcBase + ih * W + ow0;

                    AscendC::LocalTensor<float> xLocal = xQueue_.AllocTensor<float>();
                    const AscendC::DataCopyExtParams xParams(1, ow * sizeof(float), 0, 0, 0);
                    const AscendC::DataCopyPadExtParams<float> xPadParams(true, 0, 2, 0.0f);
#pragma unroll
                    for (uint32_t kw = 0; kw < KW; ++kw) {
                        AscendC::DataCopyPad(xLocal[kw * ALIGNED_TILE], xGm[xRowBase + kw],
                                            xParams, xPadParams);
                    }
                    xQueue_.EnQue(xLocal);
                    xLocal = xQueue_.DeQue<float>();

                    const uint32_t wRowBase = wCociBase + kh * KW;
                    const uint32_t weightOffset = wRowBase - wCoBase;
#pragma unroll
                    for (uint32_t kw = 0; kw < KW; ++kw) {
                        const float weightValue = weightLocal.GetValue(weightOffset + kw);
                        AscendC::Muls(tmpLocal, xLocal[kw * ALIGNED_TILE], weightValue, ow);
                        AscendC::Add(accLocal, accLocal, tmpLocal, ow);
                    }

                    xQueue_.FreeTensor(xLocal);
                }
            }

            weightQueue_.FreeTensor(weightLocal);

            AscendC::LocalTensor<float> outputLocal = outputQueue_.AllocTensor<float>();
            AscendC::DataCopy(outputLocal, accLocal, ALIGNED_TILE);
            outputQueue_.EnQue(outputLocal);
            outputLocal = outputQueue_.DeQue<float>();
            const AscendC::DataCopyExtParams outputParams(1, ow * sizeof(float), 0, 0, 0);
            AscendC::DataCopyPad(yGm[yBase], outputLocal, outputParams);
            outputQueue_.FreeTensor(outputLocal);
        }
    }

private:
    static constexpr uint32_t ALIGNED_TILE = 1024;
    static constexpr uint32_t KW_PLANES = 3;
    static constexpr uint32_t WEIGHT_ELEMS = 16 * 3 * 3;

    AscendC::TPipe pipe_;
    AscendC::TQue<AscendC::TPosition::VECIN, 1> xQueue_;
    AscendC::TQue<AscendC::TPosition::VECIN, 1> weightQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, 1> outputQueue_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> accBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf_;

    AscendC::GlobalTensor<float> xGm;
    AscendC::GlobalTensor<float> wGm;
    AscendC::GlobalTensor<float> yGm;

    uint32_t rows_{0};
    uint32_t ow_{0};
    uint32_t H_{0};
    uint32_t W_{0};
    uint32_t CIN_{0};
    uint32_t COUT_{0};
    uint32_t HO_{0};
    uint32_t tileOw_{1022};
    uint32_t owTiles_{0};
    uint32_t tasks_{0};
};

