    __aicore__ inline void Init(GM_ADDR x, GM_ADDR w, GM_ADDR y, uint32_t totalElems, uint32_t blockDim)
    {
        xGm.SetGlobalBuffer((__gm__ float*)x);
        wGm.SetGlobalBuffer((__gm__ float*)w);
        yGm.SetGlobalBuffer((__gm__ float*)y);
        totalElems_ = totalElems;
        blockDim_ = (blockDim == 0) ? 1 : blockDim;
        pipe.InitBuffer(inputQueue, 1, 147456);
        pipe.InitBuffer(weightQueue, 1, 128);
        pipe.InitBuffer(outputQueue, 1, 16256);
        pipe.InitBuffer(tempBuf, 16256);
    }

    __aicore__ inline void Process()
    {
        constexpr uint32_t N = 16;
        constexpr uint32_t CIN = 3;
        constexpr uint32_t H = 256;
        constexpr uint32_t W = 256;
        constexpr uint32_t D = 10;

        constexpr uint32_t COUT = 64;
        constexpr uint32_t HOUT = 254;
        constexpr uint32_t WOUT = 254;
        constexpr uint32_t DOUT = 10;
        constexpr uint32_t XsCI = H * W * D;
        constexpr uint32_t XsN = CIN * H * W * D;
        constexpr uint32_t YsH = WOUT * DOUT;
        constexpr uint32_t YsCO = HOUT * WOUT * DOUT;
        constexpr uint32_t YsN = COUT * HOUT * WOUT * DOUT;
        constexpr uint32_t PADDED_D = 16;
        constexpr uint32_t PADDED_INPUT_ROW = W * PADDED_D;
        constexpr uint32_t PADDED_OUTPUT_ROW = WOUT * PADDED_D;
        constexpr uint32_t PATCH_ELEMS = 3 * PADDED_INPUT_ROW;
        constexpr uint32_t TOTAL_TASKS = N * COUT * HOUT;

        const uint32_t bid = static_cast<uint32_t>(AscendC::GetBlockIdx());
        for (uint32_t task = bid; task < TOTAL_TASKS; task += blockDim_) {
            uint32_t t = task;
            const uint32_t ho = t % HOUT;
            t /= HOUT;
            const uint32_t co = t % COUT;
            const uint32_t n = t / COUT;

            AscendC::LocalTensor<float> inputLocal = inputQueue.AllocTensor<float>();
            const AscendC::DataCopyExtParams inputCopy(W, D * sizeof(float), 0, 0, 0);
            const AscendC::DataCopyPadExtParams<float> inputPad(true, 0, PADDED_D - D, 0.0f);
#pragma unroll
            for (uint32_t ci = 0; ci < CIN; ++ci) {
#pragma unroll
