                    const uint32_t xOffset = n * XsN + ci * XsCI + (ho + kh) * W * D;
                    const uint32_t ubOffset = ci * PATCH_ELEMS + kh * PADDED_INPUT_ROW;
                    AscendC::DataCopyPad(inputLocal[ubOffset], xGm[xOffset], inputCopy, inputPad);
                }
            }
            inputQueue.EnQue(inputLocal);

            AscendC::LocalTensor<float> weightLocal = weightQueue.AllocTensor<float>();
            const AscendC::DataCopyExtParams weightCopy(1, 27 * sizeof(float), 0, 0, 0);
            const AscendC::DataCopyPadExtParams<float> weightPad(true, 0, 5, 0.0f);
            AscendC::DataCopyPad(weightLocal, wGm[co * 27], weightCopy, weightPad);
            weightQueue.EnQue(weightLocal);

            inputLocal = inputQueue.DeQue<float>();
            weightLocal = weightQueue.DeQue<float>();
            AscendC::LocalTensor<float> outputLocal = outputQueue.AllocTensor<float>();
            AscendC::LocalTensor<float> tempLocal = tempBuf.Get<float>();
            AscendC::Duplicate(outputLocal, 0.0f, static_cast<int32_t>(PADDED_OUTPUT_ROW));

#pragma unroll
            for (uint32_t ci = 0; ci < CIN; ++ci) {
#pragma unroll
                for (uint32_t kh = 0; kh < 3; ++kh) {
