                                      static_cast<int32_t>(PADDED_OUTPUT_ROW));
                        AscendC::Add(outputLocal, outputLocal, tempLocal,
                                     static_cast<int32_t>(PADDED_OUTPUT_ROW));
                    }
                }
            }

            outputQueue.EnQue(outputLocal);
            outputLocal = outputQueue.DeQue<float>();
            const uint32_t yOffset = n * YsN + co * YsCO + ho * YsH;
            const AscendC::DataCopyExtParams outputCopy(WOUT, DOUT * sizeof(float), 0, 0, 0);
            AscendC::DataCopyPad(yGm[yOffset], outputLocal, outputCopy);
            outputQueue.FreeTensor(outputLocal);
            inputQueue.FreeTensor(inputLocal);
            weightQueue.FreeTensor(weightLocal);
        }
    }

private:
