            }

            const int64_t wBase = (int64_t)oc * (CIN * K * K * K);
            AscendC::LocalTensor<float> weightLocal = weightQueue_.AllocTensor<float>();
            const AscendC::DataCopyExtParams weightCopyParams(1, 81 * sizeof(float), 0, 0, 0);
            const AscendC::DataCopyPadExtParams<float> weightPadParams(true, 0, 7, 0.0f);
            AscendC::DataCopyPad(weightLocal, wGm[wBase], weightCopyParams, weightPadParams);
            weightQueue_.EnQue(weightLocal);
            weightLocal = weightQueue_.DeQue<float>();

            AscendC::Duplicate(accLocal, 0.0f, 64);
            const AscendC::DataCopyExtParams windowCopyParams(1, WO * sizeof(float), 0, 0, 0);
            const AscendC::DataCopyPadExtParams<float> windowPadParams(true, 0, 2, 0.0f);
#pragma unroll
            for (int p = 0; p < 27; ++p) {
                const int weightOffset = p * 3;
#pragma unroll
                for (int kx = 0; kx < 3; ++kx) {
                    AscendC::LocalTensor<float> xLocal = xQueue_.AllocTensor<float>();
                    AscendC::DataCopyPad(xLocal, xGm[pBase[p] + kx], windowCopyParams, windowPadParams);
                    xQueue_.EnQue(xLocal);
                    xLocal = xQueue_.DeQue<float>();

