            AscendC::DataCopy(yLocal, accLocal, 64);
            yQueue_.EnQue(yLocal);
            yLocal = yQueue_.DeQue<float>();
            const AscendC::DataCopyExtParams outputCopyParams(1, WO * sizeof(float), 0, 0, 0);
            AscendC::DataCopyPad(yGm[yRowBase], yLocal, outputCopyParams);
            yQueue_.FreeTensor(yLocal);
            weightQueue_.FreeTensor(weightLocal);
        }
    }

private:
    AscendC::GlobalTensor<float> xGm;
    AscendC::GlobalTensor<float> wGm;
    AscendC::GlobalTensor<float> yGm;
    AscendC::TPipe pipe_;
    AscendC::TQue<AscendC::TPosition::VECIN, 1> xQueue_;
    AscendC::TQue<AscendC::TPosition::VECIN, 1> weightQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, 1> yQueue_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> accBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf_;
    uint32_t blockDim_{1};
};

